async function main() {
  // Get all city IDs
  const cities = await prisma.city.findMany({
    where: { region: 'LATIN_AMERICA' },
    select: { id: true, slug: true }
  });
  const cityMap = {};
  cities.forEach(c => cityMap[c.slug] = c.id);
  console.log('Found ' + cities.length + ' LATAM cities');

  let spotCreated = 0, spotSkipped = 0, expCreated = 0, expSkipped = 0;

  // Seed spots
  for (const [citySlug, spots] of Object.entries(SPOTS_BY_CITY)) {
    const cityId = cityMap[citySlug];
    if (!cityId) { console.log('SKIP spots (no city): ' + citySlug); continue; }
    for (const spot of spots) {
      const { tags, ...data } = spot;
      const exists = await prisma.spot.findFirst({ where: { cityId, slug: data.slug } });
      if (exists) { spotSkipped++; continue; }
      await prisma.spot.create({ data: { ...data, cityId, published: true, tags: { create: tags.map(t => ({ tag: t })) } } });
      spotCreated++;
      console.log('  spot: ' + data.name);
    }
  }

  // Get a seed organizer ID
  const organizer = await prisma.experienceOrganizer.findFirst();
  if (!organizer) { console.error('No organizer found — run base seed first'); process.exit(1); }
  const organizerId = organizer.id;

  const CAT_MAP = { CULTURAL: 'ARTS_CULTURE', OUTDOOR: 'OUTDOOR_ADVENTURE', FOOD_DRINK: 'FOOD_DRINK', NIGHTLIFE: 'NIGHTLIFE_SOCIAL' };
  function minutesToStr(m) {
    if (!m) return '3 hours';
    if (m < 120) return m + ' minutes';
    const h = Math.round(m / 60);
    return h + (h === 1 ? ' hour' : ' hours');
  }

  // Seed experiences
  for (const [citySlug, experiences] of Object.entries(EXPERIENCES_BY_CITY)) {
    const cityId = cityMap[citySlug];
    if (!cityId) { console.log('SKIP experiences (no city): ' + citySlug); continue; }
    for (const exp of experiences) {
      const exists = await prisma.experience.findFirst({ where: { cityId, slug: exp.slug } });
      if (exists) { expSkipped++; continue; }
      const cat = CAT_MAP[exp.category] || exp.category;
      const gs = exp.groupSize || 12;
      await prisma.experience.create({
        data: {
          slug: exp.slug,
          name: exp.name,
          description: exp.description,
          price: exp.price,
          category: cat,
          duration: minutesToStr(exp.duration),
          groupSizeMin: 1,
          groupSizeMax: gs,
          frequency: 'daily',
          bookingUrl: exp.bookingUrl || '',
          photoUrl: exp.imageUrl || null,
          cityId,
          organizerId,
          isActive: true,
        }
      });
      expCreated++;
      console.log('  exp: ' + exp.name);
    }
  }

  console.log('\nDone! Spots: created=' + spotCreated + ' skipped=' + spotSkipped);
  console.log('Experiences: created=' + expCreated + ' skipped=' + expSkipped);
  await prisma.$disconnect();
}

main().catch(e => { console.error(e); process.exit(1); });
